            <div id="scriptPanel" style="height:0;flex-shrink:0;border-top:2px solid #3c3c3c;display:none;flex-direction:column;overflow:hidden;background:#1e1e1e;transition:height 0.15s;">
                <div style="display:flex;background:#252526;border-bottom:1px solid #3c3c3c;align-items:center;flex-shrink:0;padding:0 6px;gap:4px;">
                    <span style="color:#9cdcfe;font-size:10px;font-weight:bold;">Scene Script (iobroker)</span>
                    <div style="flex:1;"></div>
                    <button id="runScriptBtn" class="tb-btn" style="padding:2px 10px;font-size:10px;">&#9654; Apply</button>
                </div>
                <iobroker-webui-monaco-editor id="scriptMonaco" language="javascript" style="flex:1;min-height:0;"></iobroker-webui-monaco-editor>
            </div>
